@extends('admin.layout') @section('heading',$item->exists?'Документ':'Новый документ') @section('content')<form method="post" enctype="multipart/form-data" action="{{$item->exists?route('admin.documents.update',$item):route('admin.documents.store')}}">@csrf @if($item->exists)@method('PUT')@endif<div class="form-grid"><div class="panel"><div class="field"><label>Название</label><input name="title" value="{{old('title',$item->title)}}" required></div><div class="field"><label>Краткое описание</label><textarea name="description">{{old('description',$item->description)}}</textarea></div><div class="field"><label>Категория сведений</label><select name="category" required><option value="">— выберите раздел —</option>@foreach($categories as $category)<option value="{{$category}}" @selected(old('category',$item->category)===$category)>{{$category}}</option>@endforeach</select></div><div class="field"><label>Файл PDF / DOC / XLS</label><input type="file" name="file" accept=".pdf,.doc,.docx,.xls,.xlsx" {{$item->exists?'':'required'}}>@if($item->file)<small>Сейчас: {{basename($item->file)}}. Новый файл заменит текущий.</small>@endif</div></div><aside class="panel"><div class="field"><label>Номер документа</label><input name="number" value="{{old('number',$item->number)}}"></div><div class="field"><label>Дата документа</label><input type="date" name="document_date" value="{{old('document_date',$item->document_date?->format('Y-m-d'))}}"></div><div class="field"><label>Дата публикации</label><input type="date" name="published_at" value="{{old('published_at',$item->published_at?->format('Y-m-d'))}}"></div><div class="field"><label>Порядок</label><input type="number" name="sort" value="{{old('sort',$item->sort??0)}}"></div><label class="check"><input type="checkbox" name="is_published" value="1" @checked(old('is_published',$item->is_published??true))> Опубликован</label><p><button class="button">Сохранить</button></p></aside></div></form>@endsection